CREATE TABLE page_recommendations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, page_id BIGINT UNSIGNED NOT NULL, website_id INT UNSIGNED NOT NULL, content MEDIUMTEXT NOT NULL, source VARCHAR(20) NOT NULL DEFAULT 'manual', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(page_id) REFERENCES pages(id) ON DELETE CASCADE, FOREIGN KEY(website_id) REFERENCES websites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
